// firebase.js
import { initializeApp } from "firebase/app";
import { getAnalytics } from "firebase/analytics";
import { getAuth, GoogleAuthProvider, signInWithPopup } from "firebase/auth";

// TODO: Add SDKs for Firebase products that you want to use
// https://firebase.google.com/docs/web/setup#available-libraries

// Your web app's Firebase configuration
const firebaseConfig = {
  apiKey: "AIzaSyBi6uJ-JRWjhMeG6Rl92xDKfcZ4Tui5A0k",
  authDomain: "reachfoundationngo.firebaseapp.com",
  projectId: "reachfoundationngo",
  storageBucket: "reachfoundationngo.firebasestorage.app",
  messagingSenderId: "149898942009",
  appId: "1:149898942009:web:ecb4a5484706e13e0b9fe8",
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);
const analytics = getAnalytics(app);

// Google Authentication Setup
const provider = new GoogleAuthProvider();
const auth = getAuth();

// Add these scopes to ensure we get the required information
provider.addScope("email");
provider.addScope("profile");

// Force account selection to avoid cached login issues
provider.setCustomParameters({
  prompt: "select_account",
});

export const authWithGoogle = async () => {
  try {
    const result = await signInWithPopup(auth, provider);
    const user = result.user;

    // Verify we have required data
    if (!user.email || !user.displayName) {
      throw new Error("Missing required user information from Google");
    }

    // Get the ID token
    const idToken = await user.getIdToken();

    if (!idToken) {
      throw new Error("Failed to obtain ID token");
    }

    // Return just the user object (not wrapped in an object)
    // This matches what your frontend expects
    return user;
  } catch (error) {
    // Handle specific Firebase errors
    if (error.code === "auth/popup-closed-by-user") {
      throw new Error("Sign-in was cancelled by user");
    } else if (error.code === "auth/popup-blocked") {
      throw new Error("Popup was blocked. Please allow popups and try again");
    } else if (error.code === "auth/cancelled-popup-request") {
      throw new Error(
        "Multiple popup requests detected. Please wait and try again",
      );
    } else if (error.code === "auth/internal-error") {
      throw new Error("Internal authentication error. Please try again");
    }

    throw error;
  }
};
